insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 8, 'Porém tu, filho do homem, ouve o que eu te falo; não sejas rebelde como a casa rebelde; abre a tua boca, e come o que eu te dou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 9, 'Então eu vi e eis que uma mão foi estendida para mim, e eis que nela havia um rolo de livro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 10, 'E o estendeu diante de mim, e estava escrito pela frente, e por detrás: e nele estavam escritas lamentações, suspiros, e ais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 1, 'Depois me disse: Filho do homem, come o que achares; come este rolo, vai, e fala à casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 2, 'Então abri minha boca, e me fez comer aquele rolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 3, 'E disse-me: Filho do homem, faze com que teu ventre coma, e enche tuas entranhas deste rolo que eu te dou. Então o comi, e foi em minha boca doce como o mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 4, 'E disse-me: Filho do homem, vai, entra na casa de Israel, e fala-lhes com minhas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 5, 'Pois tu não és enviado a um povo de fala estranha nem de língua difícil, mas sim à casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 6, 'Nem a muitos povos de fala estranha nem de língua difícil, cujas palavras não podes entender; se eu a eles te enviasse, eles te dariam ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 7, 'Porém a casa de Israel não quererá te ouvir, pois não querem ouvir a mim; pois toda a casa de Israel é obstinada de testa e dura de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 8, 'Eis que eu fiz teu rosto forte contra os rostos deles, e tua testa forte contra a testa deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 9, 'Fiz tua testa como o diamante, mais forte que a pederneira; não os temas, nem te espantes da presença deles, ainda que sejam uma casa rebelde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 10, 'Disse-me mais: Filho do homem, toma em teu coração todas a minhas palavras que te falarei, e ouve com os teus ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 11, 'Então vai, e chega aos do cativos, aos filhos de teu povo, e tu lhes falarás e lhes dirás: Assim diz o Senhor DEUS; quer ouçam, quer deixem de ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 12, 'Então o Espírito me levantou, e ouvi detrás de mim uma voz de grande estrondo, [que dizia] : Bendita seja a glória do SENHOR desde o seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 13, '[Ouvi] também o som das asas dos animais, que tocavam umas às outras, e o som das rodas em frente deles, e som de grande estrondo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 14, 'Assim o Espírito me levantou, e me tomou; e fui com amargura, pela indignação de meu espírito; mas a mão do SENHOR era forte sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 15, 'E vim aos do cativeiro, a Tel-Abibe, que moravam junto ao rio de Quebar, e eu morava onde eles moravam; e ali permaneci sete dias atônito entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 16, 'E aconteceu que, ao fim de sete dias, veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 17, 'Filho do homem, eu te pus por vigia sobre a casa de Israel; portanto tu ouvirás a palavra de minha boca, e os alertarás de minha parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 18, 'Quando eu disser ao perverso: ‘Certamente morrerás’, e tu não o alertares, nem falares para alertar ao perverso acerca do seu caminho perverso, a fim de o conservar em vida, aquele perverso morrerá na sua maldade, porém demandarei o sangue dele da tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 19, 'Mas se tu alertares ao perverso, e ele não se converter de sua perversidade, e de seu perverso caminho, ele morrerá por sua maldade, e tu terás livrado tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 20, 'Semelhantemente, quando o justo se desviar de sua justiça, e fizer maldade, e eu puser [algum] tropeço diante dele, ele morrerá, porque tu não o alertaste; por seu pecado morrerá, e suas justiças que havia feito não serão lembradas; mas demandarei o sangue dele da tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 21, 'Porém se tu alertares ao justo, para que o justo não peque, e ele não pecar, certamente viverá, porque foi alertado; e tu terás livrado tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 22, 'E a mão do SENHOR estava ali sobre mim; e disse-me: Levanta-te, e sai ao vale; e ali falarei contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 23, 'Então eu me levantei, e saí ao vale; e eis que a glória do SENHOR estava ali, como a glória que vi junto ao rio de Quebar; e caí sobre meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 24, 'Então o Espírito entrou em mim, e fez-me ficar de pé; e falou comigo, e disse-me: Entra, e fecha-te dentro de tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 25, 'Pois tu, ó filho do homem, eis que porão cordas sobre ti, e com elas te amarrarão, por isso não sairás entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 26, 'E farei com que tua língua se apegue ao teu céu da boca, e ficarás mudo, e não lhes servirás de repreensor; pois são uma casa rebelde'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 3, 27, 'Mas quando eu falar contigo, abrirei a tua boca, e lhes dirás: Assim diz o Senhor DEUS; quem ouvir, ouça; e quem deixar [de ouvir] ,deixe; pois são uma casa rebelde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 1, 'E tu, filho do homem, toma para ti um tijolo, põe-o diante de ti, e desenha sobre ele a cidade de Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 2, 'E põe um cerco contra ela, e edifica contra ela uma fortaleza, e levanta uma rampa contra ela; e põe acampamentos contra ela, e ordena contra ela aríetes ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 3, 'E tu, toma para ti uma assadeira de ferro, e põe-a como muro de ferro entre ti e a cidade; e endireita tua face contra ela, e assim será cercada, e a cercarás. Isto será um sinal para a casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 4, 'E tu deita sobre teu lado esquerdo, e põe sobre ele a maldade da casa de Israel; [conforme] o número de dias que deitares sobre ele, levarás suas maldades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 5, 'Pois eu te dei os anos da maldade deles conforme o número de dias: trezentos e noventa dias; e tu levarás a maldade da casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 6, 'E quando completardes estes, voltarás a deitar sobre teu lado direito, e levarás a maldade da casa de Judá por quarenta dias; dei para ti um dia para cada ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 7, 'Portanto dirigirás teu rosto ao cerco de Jerusalém firmarás teu rosto, e [manterás] teu braço descoberto; e profetizarás contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 8, 'E eis que porei sobre ti cordas, e não te virarás de teu lado ao para o outro, enquanto não houveres completado os dias de teu cerco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 9, 'E tu, toma para ti trigo, cevada, favas, lentilhas, milho miúdo, e aveia, e põe-os em uma vasilha, e faz para ti pão deles, [conforme] o número de dias que dormires sobre teu lado; trezentos e noventa dias comerás disso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 10, 'E a comida que comerás será do peso de vinte siclos cada dia; de tempo em tempo a comerás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 11, 'Também beberás a água por medida: a sexta parte de um him; de tempo em tempo beberás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 12, 'E a comerás como [se fosse] pão de cevada; e a cozerás com as fezes que saem do homem, diante dos olhos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 13, 'E disse o SENHOR: Assim os filhos de Israel comerão seu pão imundo entre as nações, para onde eu os lançarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 14, 'Então eu disse: Ah Senhor DEUS! Eis que minha alma não foi contaminada; porque nunca comi coisa morta nem despedaçada, desde minha juventude até agora, nem nunca entrou em minha boca carne imunda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 15, 'E ele me disse: Eis que te dou fezes de vacas em lugar dos fezes humanas; e prepararás teu pão com elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 16, 'Então me disse: Filho do homem, eis que destruirei o sustento do pão em Jerusalém, e comerão o pão por peso, e com angústia; e beberão a água por medida, e com espanto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 4, 17, 'Para que lhes falte o pão e o água, e se espantem uns aos outros, e se consumam em suas maldades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 1, 'E tu, filho do homem, toma para ti uma espada afiada [que te sirva como] navalha de barbeiro; toma, e faze-a passar por tua cabeça e por tua barba; depois toma para ti um peso de balança, e reparte [os cabelos] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 2, 'Uma terceira parte queimarás com fogo no meio da cidade, quando se completarem os dias do cerco; então tomarás [outra] terceira parte, ferindo com espada ao redor dela; e a [outra] terceira parte espalharás ao vento; pois eu desembainharei a espada atrás deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 3, 'Tomarás também dali alguns poucos [cabelos] , e os atarás nas bordas [de] tua [roupa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 4, 'E tomarás outra vez deles, e os lançarás no meio do fogo, e com fogo os queimarás; dali sairá um fogo contra toda a casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 5, 'Assim diz o Senhor DEUS: Esta é Jerusalém, a qual eu pus no meio das nações, e das terras ao redor dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 6, 'Porém ela se rebelou contra meus juízos mais que as nações, e contra meus estatutos mais que as terras que estão ao redor dela; pois rejeitaram meus juízos, e não andaram conforme meus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 7, 'Portanto assim diz o Senhor DEUS: Por haverdes vos rebelado mais que as nações que estão ao redor de vós, não haverdes andado em meus estatutos, nem obedecido minhas leis, nem sequer conforme as leis das nações que estão ao redor de vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 8, 'Por isso assim diz o Senhor DEUS: Eis que eu, eu mesmo, estou contra ti; e farei julgamentos no meio de ti diante dos olhos das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 9, 'E farei em ti o que nunca fiz, nem jamais farei coisa semelhante, por causa da todas as tuas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 10, 'Por isso os pais comerão aos filhos no meio de ti, e os filhos comerão a seus pais; e farei em ti julgamentos, e espalharei a todos os ventos todos os teus sobreviventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 11, 'Portanto, vivo eu,diz o Senhor DEUS, (por teres profanado meu santuário com todas as tuas coisas detestáveis, e com todas as tuas abominações), que certamente eu também te quebrantarei; meu olho não perdoará, nem terei eu misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 12, 'A terceira parte de ti morrerá de pestilência, e será consumida de fome no meio de ti; a [outra] terceira parte cairá à espada ao redor de ti; e [outra] terceira parte espalharei a todos os ventos, e atrás deles desembainharei a espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 13, 'Assim se cumprirá minha ira, e farei repousar meu furor neles, e me consolarei; e saberão que eu, o SENHOR, tenho falado em meu zelo, quando tiver cumprido meu furor neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 14, 'E te tonarei em desolação e em humilhação entre as nações que estão ao redor de ti, diante dos olhos de todos os que passarem por perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 15, 'E a humilhação e a infâmia servirão de lição e espanto às nações que estão ao redor de ti, quando eu executar em ti julgamentos com ira e com furor, e com enfurecidos castigos. Eu, o SENHOR, falei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 16, 'Quando eu enviar contra eles as más flechas da fome, que servirão para destruição, as quais eu mandarei para vos destruir, então aumentarei a fome sobre vós, e destruirei vosso sustento de pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 5, 17, 'E enviarei sobre vós a fome, e animais ruins, que vos deixarão sem filhos; e a pestilência e o sangue passarão por ti; e trarei a espada sobre ti. Eu, o SENHOR, falei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 2, 'Filho do homem, põe teu rosto direcionado aos montes de Israel, e profetiza contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 3, 'E digas: Montes de Israel, ouvi palavra do Senhor DEUS; assim diz o Senhor DEUS aos montes e aos morros, aos ribeiros e aos vales: Eis que eu, eu mesmo, trarei a espada sobre vós, e destruirei vossos altos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 4, 'E vossos altares serão arruinados, e vossas imagens do sol serão quebradas; e derrubarei vossos mortos diante de vossos ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 5, 'E porei os cadáveres dos filhos de Israel diante de seus ídolos; e espalharei vossos ossos ao redor de vossos altares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 6, 'Em todas as vossas habitações as cidades serão destruídas, e os altos serão arruinados, para que vossos altares sejam destruídos e arruinados; e vossos ídolos se quebrem, e deixem de existir; e vossas imagens do sol sejam cortadas, e desfeitas vossas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 7, 'E os mortos cairão no meio de vós; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 8, 'Porém deixarei um restante, para que tenhais [alguns] que escapem da espada entre as nações, quando fordes dispersos pelas terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 9, 'Então os que escaparem de vós se lembrarão de mim entre as nações para onde forem levados em cativeiro; [lembrarão de] como eu me quebrantei por causa de seu coração infiel, que se desviou de mim, e por causa de seus olhos, que se prostituíram atrás seus ídolos; e terão nojo de si mesmos, por causa das maldades que fizeram em todas as suas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 10, 'E saberão que eu sou o SENHOR; não foi em vão que falei que lhes faria este mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 11, 'Assim diz o Senhor DEUS: Bate com tua mão, e pisa com teu pé, e dize: Ai de todas as malignas abominações da casa de Israel! Pois cairão pela espada, pela fome, e pela pestilência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 12, 'O que estiver longe morrerá de pestilência; e o que estiver perto cairá a espada; e o que restar e for cercado morrerá de fome; assim cumprirei meu furor contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 13, 'Então sabereis que eu sou o SENHOR, quando seus mortos estiverem em meio de seus ídolos, ao redor de seus altares, em todo morro alto, em todos os cumes dos montes, debaixo de toda árvore verde, e debaixo de todo carvalho espesso, lugares onde ofereciam incenso de cheiro suave a todos os seus ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 6, 14, 'Pois estenderei minha mão sobre eles, e tornarei a terra em desolação e vazio, mais que o deserto [da região] de Dibla, em todas as suas habitações; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 1, 'Depois a palavra do SENHOR veio a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 2, 'E tu, filho do homem, assim diz o Senhor DEUS à terra de Israel: É o fim, o fim vem sobre os quatro cantos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 3, 'Agora [veio] o fim sobre ti; pois enviarei minha ira sobre ti, e te julgarei conforme teus caminhos; e trarei sobre ti todas as tuas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 4, 'E meu olho não te poupará, nem terei compaixão; ao invés disso trarei teus caminhos sobre ti, e tuas abominações estarão no meio de ti; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 5, 'Assim diz o Senhor DEUS: Uma calamidade, eis que vem uma calamidade incomparável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 6, 'Vem o fim, o fim vem; despertou-se contra ti; eis que vem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 7, 'A manhã vem para ti, ó morador da terra; o tempo vem, chegado é o dia [em que haverá] desespero, e não gritos de alegria sobre os montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 8, 'Agora logo derramarei meu furor sobre ti, cumprirei minha ira contra ti; e te julgarei conforme teus caminhos; e porei sobre ti todas as tuas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 9, 'E meu olho não poupará, nem terei compaixão; trarei sobre ti conforme teus caminhos, e no meio de ti estarão tuas abominações; e sabereis que eu, o SENHOR, sou o que firo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 10, 'Eis aqui o dia, eis que vem; a manhã já saiu; já floresceu a vara, a soberba já gerou brotos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 11, 'A violência se levantou em vara de maldade; nada [restará] deles, nem de sua multidão, nem de sua riqueza, nem de seu prestígio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 12, 'O tempo veio, achegou-se o dia; o comprador não se alegre, nem o vendedor entristeça; porque a ira está sobre toda sua multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 13, 'Pois o vendedor não voltará ao que foi vendido, enquanto estiverem vivos; porque a visão sobre toda sua multidão não será cancelada; e por causa de sua iniquidade, ninguém poderá preservar sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 14, 'Já tocaram trombeta, e prepararam tudo; porém ninguém vai à batalha, pois minha ira está sobre toda sua multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 15, 'Por fora a espada, por dentro a pestilência e a fome; o que estiver no campo morrerá à espada; e o que estiver na cidade, a fome e a pestilência o consumirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 16, 'E os sobreviventes que deles escaparem estarão pelos montes como pombas dos vales, todos gemendo, cada um por sua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 17, 'Todas mãos serão fracas, e todos joelhos serão frouxos como águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 18, 'E se vestirão de saco, e o tremor os cobrirá; em todos os rostos haverá vergonha, e todas as suas cabeças serão raspadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 19, 'Lançarão sua prata pelas ruas, e seu ouro será como algo imundo; nem sua prata nem seu ouro poderá livrá-los no dia do furor do SENHOR; não saciarão suas almas, nem encherão suas entranhas; pois isto é o tropeço de sua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 20, 'E tornaram a glória de seu ornamento em orgulho, e nela fizeram nela imagens de suas abominações e de suas coisas detestáveis; por isso eu a tornarei em coisa imunda para eles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 21, 'E a entregarei em mãos de estrangeiros para ser saqueada, e aos perversos da terra para servir de despojo; e a profanarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 22, 'E desviarei meu rosto deles, e profanarão meu lugar secreto; pois nele entrarão destruidores, e o profanarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 23, 'Faze correntes, porque a terra está cheia de julgamentos de sangues, e a cidade está cheia de violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 24, 'Por isso farei vir os mais malignos das nações, que tomarão posse de suas casas; e farei cessar a arrogância dos poderosos, e seus santuários serão profanados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 25, 'A aflição está vindo; e buscarão a paz, porém não haverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 26, 'Virá desastre sobre desastre, e haverá rumor sobre rumor; então buscarão visão de profeta; porém a Lei perecerá do sacerdote, e também o conselho dos anciãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 7, 27, 'O rei lamentará, e o príncipe se vestirá de assolamento, e as mãos do povo da terra serão atemorizadas; conforme seu caminho farei com eles, e com os seus juízos os julgarei; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 1, 'E sucedeu no sexto ano, no sexto [mês] , aos cinco do mês, estando eu sentado em minha casa, e os anciãos de Judá estavam sentados diante de mim, que ali a mão do Senhor DEUS caiu sobre mim .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 2, 'E olhei, e eis uma semelhança, com aparência de fogo; desde a aparência de sua cintura para baixo, era fogo; e desde sua cintura para cima, com a aparência de um resplendor, como a cor de âmbar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 3, 'E estendeu a forma de uma mão, e tomou-me pelos cabelos de minha cabeça; e o espírito me levantou entre a terra e o céu, e me trouxe a Jerusalém em visões de Deus, até a entrada da porta de dentro que está voltada ao norte, onde estava o lugar da imagem do ciúme, que provoca ciúme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 4, 'E eis que a a glória do Deus de Israel estava ali, conforme a visão que eu tinha visto no vale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 5, 'E disse-me: Filho do homem, levanta agora teus olhos para o norte. E levantei meus olhos para o norte, e eis que a imagem do ciúme estava ao lado norte, junto à porta do altar, na entrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 6, 'Então me disse: Filho do homem, vês tu o que eles estão fazendo? As grandes abominações que a casa de Israel faz aqui, para me afastar de meu santuário? Porém ainda voltarás a ver abominações maiores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 7, 'E levou-me à porta do pátio; então olhei, e eis que havia um buraco na parede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 8, 'E disse-me: Filho do homem, cava agora naquela parede. E cavei na parede, e eis que havia uma porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 9, 'Então me disse: Entra, e vê as malignas abominações que eles fazem aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 10, 'E entrei, e olhei, e eis toda figura de répteis, e animais abomináveis, e todos os ídolos da casa de Israel, que estavam pintados na parede ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 11, 'E diante deles estavam setenta homens dos anciãos da casa de Israel, com Jazanias filho de Safã, que estava no meio deles, cada um com seu incensário em sua mão; e uma espessa nuvem de perfume subia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 12, 'Então me disse: Filho do homem, viste as coisas que os anciãos da casa de Israel fazem nas trevas, cada um em suas câmaras pintadas? Pois eles dizem: O SENHOR não nos vê; o SENHOR abandonou a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 13, 'E disse-me: Ainda voltarás a ver abominações maiores que estes fazem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 14, 'E me levou à entrada da porta da casa do SENHOR, que está ao lado norte; e eis ali mulheres que estavam sentadas, chorando a Tamuz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 15, 'Então me disse: Viste [isto] , filho do homem? Ainda voltarás a ver abominações maiores que estas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 16, 'E ele me levou ao pátio de dentro da casa do SENHOR; e eis que estavam à entrada do templo do SENHOR, entre o pórtico e o altar, cerca de vinte e cinco homens, com suas costas voltadas ao templo do SENHOR e seus rostos ao oriente, e eles se prostravam ao oriente, para o sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 17, 'Então me disse: Viste [isto] ,filho do homem? Por acaso é pouco para a casa de Judá fazer as abominações que fazem aqui? Pois eles têm enchido a terra de violência, e voltam a irritar-me, porque eis que põem o ramo em suas narinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 8, 18, 'Por isso eu também os tratarei com furor; meu olho não poupará, nem terei compaixão; e ainda que gritem em meus ouvidos com alta voz, mesmo assim não os ouvirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 1, 'Então ele gritou em meus ouvidos com alta voz, dizendo: Fazei chegar os encarregados de punir a cidade, e cada com sua armas destruidoras em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 2, 'E eis que seis homens vinham do caminho da porta alta, que está voltada para o norte, e cada um trazia em sua mão sua arma destruidora. E entre eles havia um homem vestido de linho, com um estojo de escrivão em sua cintura; e entraram, e se puseram junto ao altar de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 3, 'E a glória do Deus de Israel levantou-se do querubim sobre o qual estava, até a entrada da casa; e chamou ao homem vestido de linho, que tinha o estojo de escrivão à sua cintura,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 4, 'E o SENHOR lhe disse: Passa por meio da cidade, por meio de Jerusalém; e põe uma sinal na testa dos homens que suspiram e que gemem por causa de todas as abominações que se cometem no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 5, 'E aos outros disse a meus ouvidos: Passai pela cidade depois dele, e feri; vossos olhos não poupem, nem tenhais compaixão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 6, 'Matai velhos, rapazes e virgens, meninos e mulheres, até os acabardes por completo; porém não chegueis a toda pessoa sobre a qual houver o sinal; e começai desde meu santuário. Então começaram desde os anciãos que estavam diante do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 7, 'E disse-lhes: Contaminai a casa, e enchei os pátios de mortos; saí. Então saíram, e feriram na cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 8, 'E aconteceu que, havendo os ferido, e eu ficando de resto, caí sobre meu rosto, clamei, e disse: Ah, Senhor DEUS! Por acaso destruirás todo o restante de Israel, derramando tua ira sobre Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 9, 'Então me disse: A maldade da casa de Israel e de Judá é extremamente grande; e a terra se encheu de sangues, e a cidade se encheu de perversidade; pois dizem: O SENHOR abandonou a terra, e o SENHOR não vê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 10, 'Por isso quanto a mim, meu olho não poupará, nem terei compaixão; retribuirei o caminho deles sobre suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 9, 11, 'E eis que o homem vestido de linho, que tinha o estojo na cintura, trouxe resposta, dizendo: Fiz conforme o que me mandaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 1, 'Então olhei, e eis que sobre o firmamento que estava sobre a cabeça dos querubins, havia como uma pedra de safira, com a aparência de um trono, que apareceu sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 2, 'E falou ao homem vestido de linho, dizendo: Entra por entre as rodas debaixo dos querubins e enche tuas mãos de brasas acesas dentre os querubins, e as espalha sobre a cidade. E entrou diante de meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 3, 'E os querubins estavam à direita da casa quando aquele homem entrou; e a nuvem encheu o pátio de dentro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 4, 'Então a glória do SENHOR se levantou de sobre o querubim para a entrada da casa; e a casa se encheu de uma nuvem, e o pátio se encheu do resplendor da glória do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 5, 'E o som das asas dos querubins era ouvido até o pátio de fora, como a voz do Deus Todo-Poderoso quando fala.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 6, 'E sucedeu que, quando ele mandou ao homem vestido de linho, dizendo: Toma fogo dentre as rodas, dentre os querubins, então ele entrou, e ficou junto às rodas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 7, 'E um querubim estendeu sua mão dentre os querubins ao fogo que estava entre os querubins, e tomou-o, e o deu nas mãos do que estava vestido de linho; o qual [o] tomou, e saiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 8, 'E apareceu nos querubins a forma de uma mão humana debaixo de suas asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 9, 'Então olhei, e eis que quatro rodas estavam junto aos querubins, uma roda junto a um querubim, e outra roda junto ao outro querubim; e o aparência das rodas era como o de pedra de berilo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 10, 'Quanto à aparência delas, as quatro tinham uma mesma forma, como se estivesse uma roda no meio da outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 11, 'Quando se moviam, movimentavam-se sobre seus quatro lados; não se viravam quando moviam, mas para o lugar aonde se voltava a cabeça, iam atrás; nem se viravam quando moviam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 12, 'E toda o seu corpo, suas costas, suas mãos, suas asas, e as rodas, estavam cheias de olhos ao redor; os quatro tinham suas rodas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 13, 'Quanto às rodas, eu ouvi que foram chamadas de “roda giratória”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 14, 'E cada um tinha quatro rostos: o primeiro rosto era de querubim; o segundo rosto, de homem; o terceiro rosto, de leão; e o quarto rosto, de águia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 15, 'E os querubins se levantaram; este é o mesmo ser que vi no rio de Quebar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 16, 'E quando os querubins se moviam, as rodas se moviam junto com eles; e quando os querubins levantavam suas asas para se levantarem da terra, as rodas também não se viravam de junto a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 17, 'Quando eles paravam, elas paravam; e quando eles se levantavam, elas levantavam com eles: porque o espírito dos seres estava nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 18, 'Então a glória do SENHOR saiu de sobre a entrada da casa, e se pôs sobre os querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 19, 'E os querubins levantaram suas asas, e subiram da terra diante de meus olhos, quando saíram; e as rodas estavam ao lado deles; e pararam à entrada da porta oriental da casa do SENHOR, e a glória do Deus de Israel estava por cima deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 20, 'Estes são os seres que vi debaixo do Deus de Israel no rio de Quebar; e notei que eram querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 21, 'Cada um tinha quatro rostos, e cada um quatro asas; e havia semelhança de mãos humanas debaixo de seus asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 10, 22, 'E a semelhança de seus rostos era a dos rostos que vi junto ao rio de Quebar, suas aparências, e eles mesmos; cada um se movia na direção de seu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 1, 'Então o Espírito me levantou, e me trouxe à porta oriental da Casa do SENHOR, que está voltada para o oriente; e eis que estavam à entrada da porta vinte e cinco homens; e no meio deles vi a Jazanias filho de Azur, e a Pelatias filho de Benaías, príncipes do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 2, 'E disse-me: Filho do homem, estes são os homens que tramam perversidade, e dão mau conselho nesta cidade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 3, 'Os quais dizem: Não está perto [o tempo] de edificar casas; esta [cidade] é a caldeira, e nós a carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 4, 'Por isso profetiza contra eles; profetiza, ó filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 5, 'E caiu sobre mim o Espírito do SENHOR, e disse-me: Dize: Assim diz o SENHOR: Assim vós dizeis, ó casa de Israel; porque eu sei todas as coisas que sobem a vosso espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 6, 'Multiplicastes vossos mortos nesta cidade, e enchestes suas ruas de mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 7, 'Portanto, assim diz o Senhor DEUS: Vossos mortos que deitastes no meio dela, esses são a carne, e ela é a caldeira; porém eu vos tirarei do meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 8, 'Temestes a espada, e a espada trarei sobre vós, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 9, 'E vos tirarei do meio dela, e vos entregarei nas mãos de estrangeiros; e eu farei julgamentos entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 10, 'Pela espada caireis; na fronteira de Israel vos julgarei, e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 11, 'Esta [cidade] não vos servirá de caldeira, nem sereis vós a carne no meio dela; na fronteira de Israel eu vos julgarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 12, 'E sabereis que eu sou o SENHOR; pois vós não andastes em meus estatutos, nem fizestes meus juízos; em vez disso fizestes conforme os juízos das nações que estão ao redor de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 13, 'E aconteceu que, enquanto eu estava profetizando, Pelatias filho de Benaías faleceu. Então caí sobre meu rosto, clamei com alta voz, e disse: Ah, Senhor DEUS! Consumirás tu o resto de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 14, 'Então veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 15, 'Filho do homem, teus irmãos, são teus irmãos, os homens de teu parentesco e toda a casa de Israel, ela toda são a quem os moradores de Jerusalém disseram: Afastai-vos do SENHOR; a terra é dada a nós em possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 16, 'Por isso dize: Assim diz o Senhor DEUS: Ainda que os tenha lançado longe entre as nações, e tenha os dispersado pelas terras, contudo por um pouco [tempo] eu lhes serei por santuário nas terras para onde vieram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 17, 'Por isso dize: Assim diz o Senhor DEUS: Eu vos ajuntarei dos povos, e vos recolherei das terras as quais fostes dispersos, e vos darei a terra de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 18, 'E virão para lá, e tirarão dela todas suas coisas detestáveis e todas as suas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 19, 'E lhes darei um mesmo coração, e um espírito novo darei em suas entranhas; e tirarei o coração de pedra de sua carne, e lhes darei coração de carne;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 20, 'Para que andem em meus estatutos e guardem meus juízos e os pratiquem; e eles serão meu povo, e eu serei seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 21, 'Mas quanto a [aqueles] cujo coração anda conforme o desejo de suas coisas detestáveis e de suas abominações, eu retribuirei seu caminho sobre suas cabeças, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 22, 'Depois os querubins levantaram suas asas, e as rodas ao lado deles; e a glória do Deus de Israel estava por cima deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 23, 'E a glória do SENHOR subiu do meio da cidade, e se pôs sobre o monte que está ao oriente da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 24, 'Depois o Espírito me levantou, e levou-me à Caldeia, aos do cativeiro, em visão do Espírito de Deus. E a visão que vi foi embora acima de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 11, 25, 'E falei aos do cativeiro todas as palavras do SENHOR que ele havia me mostrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 2, 'Filho do homem, tu habitas em meio de uma casa rebelde, os quais têm olhos para ver mas não veem, têm ouvidos para ouvir, mas não ouvem; pois eles são uma casa rebelde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 3, 'Portanto tu, filho do homem, prepara-te bagagem de partida, e parte-te de dia diante dos olhos deles; e tu partirás de teu lugar para outro lugar diante dos olhos deles; pode ser que vejam, ainda que eles sejam uma casa rebelde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 4, 'Assim tirarás tuas bagagem, como bagagem de partida, durante dia diante de seus olhos; então tu sairás à tarde diante de seu olhos, como quem sai para se partirem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 5, 'Diante de seus olhos cava [um buraco] na parede, e tira por ele [a bagagem] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 6, 'Diante de seus olhos os levarás sobre teus ombros, ao anoitecer os tirarás; cobrirás teu rosto, para que não vejas a terra; pois eu fiz de ti por sinal à casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 7, 'E eu fiz assim como me foi mandado; tirei minha bagagem de dia, como bagagem de partida, e à tarde cavei [um buraco] na parede com a mão; tirei-os de noite, [e] os levei sobre os ombros diante dos olhos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 8, 'E veio a mim palavra do SENHOR pela manhã, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 9, 'Filho do homem, por acaso a casa de Israel, aquela casa rebelde, não te perguntou: O que estás fazendo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 10, 'Dize-lhes: Assim diz o Senhor DEUS: esta revelação é para o príncipe em Jerusalém, e para toda a casa de Israel que está em meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 11, 'Dize: Eu sou vosso sinal; tal como eu fiz, assim se fará a eles; serão removidos; irão em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 12, 'E o príncipe que está entre eles, levará nos ombros [sua bagagem] de noite, e sairá; na parede cavarão [uma abertura] para saírem por ela; cobrirá seu rosto para não ver com [seus] olhos a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 13, 'Também estenderei minha rede sobre ele, e ele será preso em meu laço, e eu o levarei à Babilônia, à terra de caldeus; porém ele não a verá, ainda que morrerá ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 14, 'E a todos os que estiverem ao redor dele para ajudá-lo, e a todas as suas tropas espalharei a todos os ventos, e desembainharei espada atrás deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 15, 'Assim saberão que eu sou o SENHOR, quando eu os espalhar entre as nações, e os dispersar pelas terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 16, 'Porém deixarei alguns poucos sobreviventes da espada, da fome, e da pestilência, para que contem todas as suas abominações entre as nações para onde forem; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 17, 'Então veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 18, 'Filho do homem, come teu pão com tremor, e bebe tua água com estremecimento e com ansiedade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 19, 'E dize ao povo da terra: Assim diz o Senhor DEUS sobre os moradores de Jerusalém, e sobre a terra de Israel: Comerão seu pão com ansiedade, e com espanto beberão sua água; porque sua terra será desolada de seu conteúdo, por causa da violência de todos os que nela habitam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 20, 'E as cidades habitadas serão desoladas, e a terra se tornará em deserto; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 21, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 22, 'Filho do homem, que ditado é este que vós tendes vós terra de Israel, que diz: Os dias se prolongarão, e toda visão perecerá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 23, 'Portanto dize-lhes: Assim diz o Senhor DEUS: Farei cessar este ditado, e não usarão mais esta frase em Israel. Ao invés disso, dize-lhes: Os dias chegaram, e o cumprimento de toda visão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 24, 'Porque não haverá mais uma visão falsa sequer, nem haverá adivinhação lisonjeira no meio da casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 25, 'Pois eu, o SENHOR, falarei; a palavra que eu falar se cumprirá; não se prolongará mais; porque em vossos dias, ó casa rebelde, falarei a palavra e a cumprirei, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 26, 'Também veio a mim palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 27, 'Filho do homem, eis que os da casa de Israel dizem: A visão que este vê é para muitos dias, e ele profetiza para tempos distantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 12, 28, 'Por isso dize-lhes: Assim diz o Senhor DEUS: Nenhuma das minhas palavras se prolongará mais; e palavra que eu falei se cumprirá, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 2, 'Filho do homem, profetiza contra os profetas de Israel que profetizam; e dize aos que profetizam de seu [próprio] coração: Ouvi a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 3, 'Assim diz o Senhor DEUS: Ai dos profetas tolos, que andam atrás de seu [próprio] espírito, e que nada viram!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 4, 'Teus profetas são como raposas nos desertos, ó Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 5, 'Não subistes às brechas, nem restaurastes o muro para a casa de Israel, para estardes na batalha no dia do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 6, 'Eles veem falsidade e adivinhação de mentira. Falam: O SENHOR disse, mas o SENHOR não os enviou; e [ainda] esperam que a palavra se cumpra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 7, 'Por acaso não vedes visão falsa, e não falais adivinhação de mentira, quando dizeis, O SENHOR disse, sem que eu tenha falado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 8, 'Portanto assim diz o Senhor DEUS: Dado que falais falsidade e vedes mentira, portanto eis que eu sou contra vós, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 9, 'E minha mão será contra os profetas que veem falsidade, e adivinham mentira; não estarão na congregação do meu povo, nem estarão inscritos no livro da casa de Israel, nem voltarão para a terra de Israel; e sabereis que eu sou o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 10, 'Portanto, por andarem enganando a meu povo, dizendo: Paz, sem que houvesse paz, e [quando] um edifica uma parede, eis que eles a rebocam com cal solta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 11, 'Dize aos que rebocam com cal solta, que cairá; haverá uma grande pancada de chuva, e vós ó grandes pedras de granizo, caireis, e um vento tempestuoso [a] fenderá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 12, 'E eis que, quando a parede tiver caído, não vos dirão: Onde está a reboco com que rebocastes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 13, 'Por isso assim diz o Senhor DEUS: Farei com que rompa um vento tempestuoso em meu furor e haverá uma grande pancada de chuva em minha ira, e grande pedras de granizo em indignação, para destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 14, 'E derrubarei a parede que vós rebocastes com cal solta, e a lançarei em terra, e seu fundamento ficará descoberto; assim cairá, e perecereis no meio dela; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 15, 'Assim cumprirei meu furor contra a parede, e contra os que a rebocaram com lodo solto; e vos direi: Já não há a parede, nem os que a rebocavam,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 16, 'Os profetas de Israel que profetizam sobre Jerusalém, e veem para ela visão de paz, sem que haja paz,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 17, 'E tu, filho do homem, dirige teu rosto às filhas de teu povo que profetizam de seu [próprio] coração, e profetiza contra elas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 18, 'E dize: Assim diz o Senhor DEUS: Ai daquelas que costuram almofadas para todos os pulsos, e fazem lenços sobre as cabeças de todos os tamanhos para caçarem as almas! Por acaso caçareis as almas de meu povo, e guardareis a vossas [próprias] almas em vida?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 19, 'Vós me profanastes para com meu povo por punhados de cevada e por pedaços de pão, matando as almas que não deviam morrer, e mantendo em vida as almas que não deviam viver, mentindo a meu povo, que escuta a mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 20, 'Por isso assim diz o Senhor DEUS: Eis que eu contra vossas almofadas, com que caçais as almas como [se fossem] pássaros; eu as arrancarei de vossos braços, e soltarei as almas, as almas que caçais como pássaros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 21, 'E rasgarei vossos lenços, e livrarei meu povo de vossas mãos, e não mais estarão em vossas mãos para serem caçadas; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 22, 'Pois com mentira entristecestes o coração do justo, ao qual eu não lhe causei dor, e fortalecestes as mãos do perverso, para que não se desviasse de seu mau caminho para se manter vivo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 13, 23, 'Portanto não mais vereis falsidade, nem mais adivinhareis adivinhação. Mas livrarei meu povo de vossas mãos, e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 1, 'E vieram a mim [alguns] dos anciãos de Israel, e se sentaram diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 2, 'Então veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 3, 'Filho do homem, estes levantaram ídolos em seus corações e puseram o tropeço de sua maldade diante de seus rostos. Por acaso devo eu deixar que me consultem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 4, 'Portanto fala com eles, e dize-lhes: Assim diz o Senhor DEUS: Qualquer homem da casa de Israel que levantar a seus ídolos em seu coração, e puser o tropeço de sua maldade diante de seu rosto, e vier ao profeta, eu, o SENHOR responderei ao que vier conforme a multidão de seus ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 5, 'Para eu tomar a casa de Israel em seus corações, pois todos se tornaram estranhos de mim por causa de seus ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 6, 'Portanto dize à casa de Israel: Assim diz o Senhor DEUS: Convertei-vos, virai-vos de costas a vossos ídolos, e desviai vossos rostos de todas as vossas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 7, 'Porque qualquer homem da casa de Israel, e dos estrangeiros que moram em Israel, que houver deixado de me seguir, e levantar seus ídolos em seu coração, e puser diante de seu rosto o tropeço de sua maldade, e vier ao profeta para me consultar por meio dele, eu, o SENHOR, lhe responderei por mim mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 8, 'E porei meu rosto contra tal homem, e farei com que ele seja um sinal e um ditado, e o cortarei do meio do meu povo; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 9, 'E se o profeta se enganar e falar alguma palavra, eu o SENHOR enganei ao tal profeta; e estenderei minha mão contra ele, e eu o destruirei do meio de meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 10, 'E levarão sua maldade; tal como a maldade do que pergunta, assim será a maldade do profeta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 11, 'Para que a casa de Israel não mais se desvie de me seguir, nem se contaminem mais com todas as seus transgressões; e então serão meu povo, e eu serei seu Deus, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 12, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 13, 'Filho do homem, quando uma terra pecar contra mim, rebelando-se gravemente, então estenderei minha mão contra ela, quebrarei o sustento de pão dela, mandarei nela fome, e cortarei dela homens e animais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 14, 'E ainda que estivessem no meio dela estes três homens, Noé, Daniel, e Jó, eles por sua justiça livrariam [somente] suas almas,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 15, 'E se eu fizer passar os animais perigosos pela terra, e eles a despojarem, e ela for tão assolada que ninguém possa passar por ela por causa dos animais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 16, 'e estes três homens estivessem no meio dela, vivo eu, diz o Senhor DEUS, que não livrariam nem filhos nem filhas; somente eles ficariam livres, e a terra seria assolada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 17, 'Ou [se] eu trouxer a espada sobre a tal terra, e disser: Espada, passa pela terra; e eu exterminar dela homens e animais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 18, 'Ainda que estes três homens estivessem nela, vivo eu,diz o Senhor DEUS, que não livrariam filhos nem filhas; somente eles ficariam livres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 19, 'Ou [se] eu mandar pestilência sobre tal terra, e derramar meu furor sobre ela com sangue, para exterminar dela homens e animais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 20, 'Ainda que Noé, Daniel, e Jó estivessem no meio dela, vivo eu,diz o Senhor DEUS, que não livrariam filho nem filha; eles por sua justiça livrariam suas [próprias] almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 21, 'Porque assim diz o Senhor DEUS: Quanto mais se eu enviar meus quatro calamitosos julgamentos, espada, fome, animais perigosos, e pestilência, contra Jerusalém, para exterminar dela homens e animais!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 22, 'Porém eis que restarão nela [alguns] sobreviventes, filhos e filhas, que serão transportados. Eis que eles chegarão até vós, e vereis seu caminho e seus feitos; e ficareis consolados do mal que eu trouxe sobre Jerusalém, de tudo que trouxe sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 14, 23, 'E eles vos consolarão quando virdes seu caminho e seus feitos; e sabereis que não sem razão que fiz tudo quanto fiz nela,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 2, 'Filho do homem, em que é a madeira da videira é melhor que toda madeira? [Ou] o que é o sarmento entre as madeiras do bosque?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 3, 'Por acaso tomam dele madeira para fazer alguma obra? Toma-se dele alguma estaca para pendurar nela algum vaso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 4, 'Eis que é posto no fogo para ser consumido; suas duas pontas o fogo consome, e seu meio fica queimado. Por acaso serviria para alguma obra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 5, 'Eis que quando estava inteiro não se fazia [dele] obra; menos ainda depois de consumido pelo fogo, tendo se queimado, servir para obra alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 6, 'Portanto assim diz o Senhor DEUS: Tal como a madeira da videira entre as madeiras do bosque, a qual entreguei ao fogo para que seja consumida, assim entregarei os moradores de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 7, 'Pois porei meu rosto contra eles; ainda que tenham saído do fogo, o fogo os consumirá; e sabereis que eu sou o SENHOR, quando tiver posto meu rosto contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 15, 8, 'E tonarei a terra em desolação, pois transgrediram gravemente,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 2, 'Filho do homem, notifica a Jerusalém suas abominações,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 3, 'E dize: Assim diz o Senhor DEUS a Jerusalém: Tua origem e teu nascimento [procedem] da terra de Canaã; teu pai era amorreu, e tua mãe Heteia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 4, 'E quanto a teu nascimento, no dia que nasceste não foi cortado o teu umbigo, nem foste lavada com água para ficares limpa; nem foste esfregada com sal, nem foste envolvida em faixas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 5, 'Não houve olho algum que se compadecesse de ti, para te fazer algo disto, tendo misericórdia; ao invés disso, foste lançada sobre a face do campo, por nojo de tua alma, no dia em que nasceste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 6, 'E quando passei junto a ti, vi-te suja em teu sangue, e te disse em teu sangue: Vive; e te disse em teu sangue: Vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 7, 'Eu te multipliquei como o broto do campo, e cresceste, e engrandeceste; e chegaste à grande formosura; os seios te cresceram, e teu pelo cresceu; porém estavas nua e descoberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 8, 'E quando passei junto a ti, e te vi, e eis que teu tempo era tempo de amores; e estendi meu manto sobre ti, e cobri tua nudez; e prestei juramento a ti, e entrei em pacto contigo, e foste minha diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 9, 'Então te lavei com água, e te enxaguei de teu sangue, e te ungi com óleo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 10, 'E te vesti de bordado, calcei-te com couro, cingi-te de linho fino, e te cobri de seda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 11, 'E te adornei com ornamentos, e pus braceletes em teus braços, e colar em teu pescoço;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 12, 'E pus joias pendente em teu nariz, argolas em tuas orelhas, e uma linda coroa em tua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 13, 'E foste adornada de ouro e de prata, e teu vestido foi linho fino, e seda, e bordado; comeste farinha fina, mel, e azeite; foste muito formosa, e prosperaste até ser rainha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 14, 'A tua fama percorreu entre as nações por causa da tua beleza; porque era perfeita, por causa da minha glória que eu havia posto sobre ti, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 15, 'Porém confiaste na tua beleza, e te prostituíste por causa da tua fama, e derramaste tuas prostituições a todo que passava, para que fosse dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 16, 'E tomaste de teus vestidos, fizeste altares de diversas cores, e te prostituíste sobre eles: coisa semelhante não virá, nem será assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 17, 'Tomaste também os vasos de teu ornamento, que eu te dei de meu ouro e de minha prata, e fizeste para ti imagens de homens, e te prostituíste com elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 18, 'E tomaste teus vestidos bordados, e as cobriste; e puseste meu óleo e meu perfume diante delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 19, 'E o meu pão também que eu te dei, a farinha fina, o azeite, e o mel, com que eu te sustentava, puseste diante delas, como cheiro suave; e assim foi, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 20, 'Além disto, tomaste teus filhos e tuas filhas, que havias gerado para mim, e os sacrificaste a elas para que fossem consumidas. Por acaso são poucas as tuas prostituições?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 21, 'E mataste meus filhos, e os entregastes a elas para que passassem pelo [fogo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 22, 'E em todas as tuas abominações e tuas prostituições, não te lembraste dos dias de tua juventude, quando estavas nua e descoberta, quando estavas suja em teu sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 23, 'E sucedeu que, depois de toda tua maldade (Ai, ai de ti! diz o Senhor DEUS),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 24, 'Edificaste para ti uma câmara, e fizeste para ti altares em todas as ruas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 25, 'Em cada canto de caminho edificaste teu altar, fizeste abominável tua formosura, e abriste tuas pernas a todo que passava; e [assim] multiplicaste tuas prostituições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 26, 'E te prostituíste com os filhos do Egito, teus vizinhos, grandemente promíscuos; e multiplicaste tuas prostituições, para me provocar à ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 27, 'Por isso eis que estendi minha mão sobre ti, e diminuí tua provisão; e te entreguei à vontade das que te odeiam, as filhas dos filisteus, as quais se envergonhavam de teu caminho pecaminoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 28, 'Também te prostituíste com os filhos da Assíria, por seres insaciável; e te prostituindo com eles, nem ainda te fartaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 29, 'Ao invés disso multiplicaste tuas prostituições na terra de Canaã até a Caldeia; e nem ainda com isso com isto te fartaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 30, 'Como está fraco o teu coração, diz o Senhor DEUS, tendo tu feito todas estas coisas, obras de uma poderosa prostituta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 31, 'Edificando tu tuas câmaras ao canto de cada caminho, e fazendo teus altares em cada rua; e nem sequer foste como a prostituta, [pois] desprezaste o pagamento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 32, '[Mas foste] como uma mulher adúltera, que em lugar de seu marido recebe a estranhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 33, 'Todas as prostitutas são pagas; mas tu deste teus pagamentos a todos os teus amantes; e lhes deste presentes, para que viessem a ti dos lugares ao redor, por causa de tuas prostituições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 34, 'Assim acontece contigo o contrário das mulheres que se prostituem, porque ninguém te buscou para prostituir; pois quando pagas ao invés de receber pagamento, tu tens sido o contrário [das outras] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 35, 'Portanto, ó prostituta, ouve a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 36, 'Assim diz o Senhor DEUS: Visto que se derramou teu dinheiro, e tuas vergonhas foram descobertas por tuas prostituições com teus amantes, como também com todos os ídolos de tuas abominações, e no sangue de teus filhos, os quais lhes deste;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 37, 'Por isso eis que ajuntarei todos os teus amantes com os quais tiveste prazer, e também todos os que amaste, com todos quantos tu odiaste; e os ajuntarei contra ti ao redor, e descobrirei tua nudez diante deles, para que vejam toda a tua nudez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 38, 'E eu te julgarei pelas leis das adúlteras, e das que derramam sangue; e te entregarei ao sangue do furor e do ciúme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 39, 'E te entregarei na mão deles; e eles destruirão tua câmara, derrubarão teus altares, e te despirão de teus vestidos; e tomarão as joias de teu ornamento, e te deixarão nua e descoberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 40, 'Então farão subir contra ti uma multidão, e te apedrejarão com pedras, e te atravessarão com suas espadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 41, 'E queimarão tuas casas a fogo, e executarão julgamentos contra ti, diante dos olhos de muitas mulheres; e te farei cessar de ser prostituta, nem darás mais pagamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 42, 'Assim farei descansar meu furor sobre ti, meu ciúme se afastará de ti; eu me aquietarei, e não mais me indignarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 43, 'Porque não te lembraste dos dias de tua juventude, e me provocaste à ira com tudo isto, por isso eis que também eu tornarei o teu caminho sobre [tua] cabeça, diz o Senhor DEUS; por acaso não cometeste tu tal promiscuidade além de todas as tuas abominações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 44, 'Eis que todo aquele que usa de provérbios fará provérbio sobre ti, dizendo: Tal mãe, tal filha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 45, 'Tu és filha de tua mãe, que tinha nojo de seu marido e de seus filhos; e tu és irmã de tuas irmãs, que tinham nojo de seus maridos e de seus filhos; vossa mãe foi Heteia, e vosso pai amorreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 46, 'E tua irmã maior é Samaria, ela e suas filhas, a qual habita à tua esquerda; e tua irmã menor que tu é Sodoma com suas filhas, a qual habita à tua direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 47, 'Porém não andaste em seus caminhos, nem fizeste conforme suas abominações; mas em vez disso, como se fosse muito pouco, tu te corrompeste ainda mais que elas em todos os teus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 48, 'Vivo eu, diz o Senhor DEUS, que tua irmã Sodoma e suas filhas não fizeram tanto como fizeste tu e tuas filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 49, 'Eis que esta foi a maldade de tua irmã Sodoma: ela e suas filhas tiveram soberba, fartura de pão, e abundância de conforto; porém nunca ajudaram a mão do pobre e do necessitado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 50, 'E se tornaram arrogantes, e fizeram abominação diante de mim, por isso eu as tirei quando vi [isto] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 51, 'Também Samaria não cometeu sequer a metade de teus pecados; e tu multiplicaste tuas abominações mais que elas, e fizeste tuas irmãs parecerem justas em comparação a todas as tuas abominações que fizeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 52, 'Tu também, leva tua vergonha, tu que julgaste em favor de tuas irmãs por meio de teus pecados, que fizeste mais abomináveis que elas; mais justas são que tu; envergonha-te, pois, tu também, e leva tua vergonha, pois justificaste a tuas irmãs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 53, 'Eu, pois, os restaurarei de seu infortúnio, os cativos de Sodoma e de suas filhas, e os cativos de Samaria e de suas filhas, e os cativos do teu cativeiro entre elas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 54, 'Para que leves tua vergonha, e sejas envergonhada por tudo que fizeste, dando-lhes tu consolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 55, 'Enquanto tuas irmãs, Sodoma com suas filhas e Samaria com suas filhas, voltarão ao seu primeiro estado; também tu e tuas filhas voltareis a vosso primeiro estado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 56, 'Não foi tua irmã Sodoma mencionada em tua boca no tempo de tuas soberbas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 57, 'Antes que tua maldade fosse descoberta? Semelhantemente [agora é teu] tempo de humilhação pelas filhas de Síria e de todos que estavam ao redor dela, e as filhas dos filisteus ao redor, que te desprezam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 58, 'Tu levarás [a punição por] tua perversidade e tuas abominações, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 59, 'Porque assim diz o Senhor DEUS: Eu farei contigo conforme tu fizeste, que desprezaste o juramento, quebrando o pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 60, 'Contudo eu me lembrarei do meu pacto contigo nos dias de tua juventude, e estabelecerei contigo um pacto eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 61, 'Então te lembrarás de teus caminhos, e te envergonharás, quando receberes a tuas irmãs maiores que tu com as menores que tu, pois eu as darei a ti por filhas, porém não por teu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 62, 'E estabelecerei meu pacto contigo, e saberás que eu sou o SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 16, 63, 'Para que te lembres [disso] , e te envergonhes, e nunca mais abras a boca por causa de tua vergonha, quando eu me reconciliar contigo de tudo quanto fizeste, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 2, 'Filho do homem, propõe um enigma, e fala uma parábola à casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 3, 'E dize: Assim diz o Senhor DEUS: Uma grande águia, de grandes asas e de comprida plumagem, cheia de penas de várias cores, veio ao Líbano, e tomou o mais alto ramo de um cedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 4, 'Arrancou o topo de seus renovos, e o trouxe à terra de comércio; na cidade de mercadores ela o pôs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 5, 'E tomou da semente da terra, e a lançou em um campo fértil; tomando-a, plantou-a junto a grandes águas, como [se fosse] um salgueiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 6, 'E brotou, e tornou-se uma videira larga, [porém] de baixa estatura; seus ramos olhavam para ela, e suas raízes estavam debaixo dela; e tornou-se uma videira, que produzia ramos e brotava renovos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 7, 'E houve outra grande águia, de grandes asas e cheia de penas; e eis que esta videira juntou suas raízes para perto dela, e estendeu seus ramos para ela desde o lugar onde estava plantada, para que fosse regada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 8, 'Em uma boa terra, junto a muitas águas ela estava plantada, para produzir ramos e dar fruto, para que fosse uma videira excelente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 9, 'Dize: Assim diz o Senhor DEUS: Por acaso [a videira] terá sucesso? Não arrancará [a águia] suas raízes, e cortará seu fruto, e se secará? Todas as folhas que dela brotavam se secarão; e nem [é necessário] um braço grande, nem muita gente, para a arrancar desde suas raízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 10, 'Mas eis que, [mesmo] estando plantada, terá ela sucesso? Por acaso, quando o vento oriental a tocar, ela não se secará por completo? Nos canteiros de seus renovos se secará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 11, 'Então veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 12, 'Dize agora à casa rebelde: Por acaso não sabeis o que significam estas coisas? Dize-lhes: Eis que o rei da Babilônia veio a Jerusalém, tomou o teu rei e seus príncipes, e os levou consigo à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 13, 'E tomou [um] da família real, fez pacto com ele, fazendo-lhe prestar juramento; e tomou os poderosos da terra [consigo] ,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 14, 'Para que o reino ficasse humilhado, e não se levantasse; mas podendo continuar a existir se guardasse seu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 15, 'Porém rebelou-se contra ele, enviando seus mensageiros ao Egito, para que lhe dessem cavalos e muita gente. Por acaso terá sucesso, ou escapará aquele que faz tais coisas? Poderá quebrar o pacto, e [ainda assim] escapar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 16, 'Vivo eu, diz o Senhor DEUS, que morrerá em meio da Babilônia, no lugar do rei que o fez reinar, cujo juramento desprezou, e cujo pacto quebrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 17, 'E Faraó não lhe fará coisa alguma nem com grande exército, nem com muita multidão na batalha, quando levantarem cerco e edificarem fortificações para destruírem muitas vidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 18, 'Porque desprezou o juramento, quebrando o pacto; e eis que havia firmado compromisso; havendo pois feito todas todas estas coisas, não escapará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 19, 'Por isso assim diz o Senhor DEUS: Vivo eu, que meu juramento que ele desprezou, e meu pacto que ele quebrou, isto retribuirei sobre sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 20, 'E estenderei sobre ele minha rede, e ficará preso em minha malha; e eu o levarei à Babilônia, e ali entrarei em juízo contra ele, por sua rebeldia com que se rebelou contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 21, 'E todos os seus fugitivos com todas as suas tropas cairão à espada, e os que restarem serão dispersos a todos os ventos; e sabereis que fui eu, o SENHOR, que falei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 22, 'Assim diz o Senhor DEUS: Também eu tomarei do topo daquele alto cedro, e o plantarei; do mais alto de seus renovos cortarei o [mais] tenro, e eu o plantarei sobre um monte alto e sublime;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 23, 'No monte alto de Israel o plantarei, e produzirá ramos, dará fruto, e se tronará um cedro excelente; e habitarão debaixo dele todas as aves, todos os que voam; e na sombra de seus ramos habitarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 17, 24, 'Assim todas os árvores do campo saberão que eu, o SENHOR, rebaixei a árvore alta, levantei a árvore baixa, sequei a árvore verde, e tornei verde a árvore seca. Eu, o SENHOR, falei, e farei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 2, 'O que vós pensais, vós que dizeis este provérbio sobre a terra de Israel, dizendo: Os pais comeram uvas verdes, mas foram os dentes dos filhos que se estragaram?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 3, 'Vivo eu,diz o Senhor DEUS, que nunca mais direis este provérbio em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 4, 'Eis que todas as almas são minhas; tanto a alma do pai como alma do filho são minhas; a alma que pecar, essa morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 5, 'Se um homem for justo, e fizer juízo e justiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 6, 'Não comer sobre os montes, nem levantar seus olhos para os ídolos da casa de Israel, nem contaminar a mulher de seu próximo, nem se achegar à mulher menstruada,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 7, 'E a ninguém oprimir; devolver ao devedor o seu penhor, não cometer roubo, der de seu pão ao faminto, e cobrir com roupa ao nu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 8, 'Não emprestar a juros, nem receber lucros; e desviar sua mão da injustiça, e fizer juízo entre dois homens com base na verdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 9, 'E andar em meus estatutos, e guardar meus juízos, para agir com base na verdade, este justo certamente viverá,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 10, 'E se ele gerar um filho ladrão, derramador de sangue, que fizer a seu irmão alguma destas coisas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 11, '(Ainda que [o pai] não faça tais coisas): como comer sobre os montes, contaminar a mulher de seu próximo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 12, 'Oprimir o pobre e o necessitado, cometer roubos, não devolver o penhor, levantar seus olhos para os ídolos, praticar abominação,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 13, 'Emprestar a juros, e receber lucro. Por acaso viveria? Não viverá. Ele fez todas estas abominações; certamente morrerá; o seu sangue será sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 14, 'E eis que se, [por sua vez] ele gerar um filho, que vir todos os pecados que seu pai fez, e olhar para não fazer conforme a eles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 15, 'Não comer sobre os montes, nem levantar seus olhos para os ídolos da casa de Israel; nem contaminar a mulher de seu próximo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 16, 'Nem oprimir a ninguém; nem retiver o penhor, nem cometer roubos; der de seu pão ao faminto, e cobrir com roupa ao nu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 17, 'Desviar sua mão de [fazer mal a] o pobre, não receber juros nem lucro; e praticar meus juízos, e andar em meus estatutos, este não morrerá pela maldade de seu pai; certamente viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 18, 'Seu pai, dado que fez opressão, roubou os bens do irmão, e fez o que não era bom no meio de seu povo, eis que morrerá por sua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 19, 'Porém dizeis: Por que o filho não será punido pela maldade do pai? Porque o filho fez juízo e justiça, guardou todas o meus estatutos, e as praticou, certamente viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 20, 'A alma que pecar, essa morrerá; o filho não será punido pela maldade do pai, nem o pai será punido pela maldade do filho; a justiça do justo será sobre ele, e a perversidade do perverso será sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 21, 'Mas se o perverso se converter de todos os seus pecados que cometeu, e [passar a] guardar todos os meus estatutos, e fizer juízo e justiça, certamente viverá; não morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 22, 'Todas as suas transgressões que cometeu não lhe serão lembradas; por sua justiça que praticou, viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 23, 'Por acaso eu prefiro a morte do ímpio?,diz o Senhor DEUS, E não que ele se converta de seus caminhos, e viva?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 24, 'Mas se o justo se desviar de sua justiça, e [passar a] praticar maldade, e fizer conforme a todas as abominações que o perverso faz, por acaso ele viveria? Todas as suas justiças que praticou não serão lembradas; por sua transgressão com que transgrediu, e por seu pecado com que pecou, por causa deles morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 25, 'Porém dizeis: O caminho do Senhor não é justo. Ouvi agora, ó casa de Israel: por acaso o meu caminho não é justo? [Ou] não são os vossos caminhos que são injustos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 26, 'Se o justo de desviar de sua justiça, e [passar a] praticar maldade, ele morrerá por ela; pela maldade que cometeu, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 27, 'Porém se o perverso se desviar de sua perversidade que cometeu, e [passar a] praticar juízo e justiça, esse conservará sua alma em vida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 28, 'Porque observou, e se converteu de todas as suas transgressões que cometera, certamente viverá, não morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 29, 'Contudo a casa de Israel diz: O caminho do Senhor não é justo. Por acaso os meus caminhos não são justos, ó casa de Israel? [Ou] não são vossos caminhos que são injustos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 30, 'Portanto eu vos julgarei a cada um conforme seus [próprios] caminhos, ó casa de Israel,diz o Senhor DEUS. Convertei-vos e desviai-vos de todas as vossas transgressões; e assim a maldade não será vossa queda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 31, 'Lançai fora de vós todas as vossas transgressões com que transgredistes, e fazei para vós um novo coração e um novo espírito. Pois por que tendes que morrer, ó casa de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 18, 32, 'Porque eu não me agrado da morte do que morre,diz o Senhor DEUS; convertei-vos, pois, e vivereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 1, 'E tu, levanta uma lamentação sobre os príncipes de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 2, 'E dize: Quem foi tua mãe? Uma leoa deitada entre os leões; entre os leõezinhos ela criou seus filhotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 3, 'E fez crescer um de seus filhotes, que veio a ser um leãozinho; e ele aprendeu a caçar presa, e a devorar homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 4, 'E as nações ouviram dele; ele foi preso na cova delas, e o trouxeram com ganchos à terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 5, 'E quando ela viu que havia esperado [muito] , e que sua esperança era perdida, tomou outro de seus filhotes, e o pôs por leãozinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 6, 'E ele andou entre os leões; tornou-se um leãozinho, aprendeu a caçar presa, e devorou homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 7, 'E conheceu suas viúvas, e destruiu suas cidades; e a terra e tudo que ela continha foram devastadas à voz de seu bramido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 8, 'Então foram contra sobre ele as nações das províncias de seu ao redor; estenderam sobre ele sua rede, e ele foi preso na cova delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 9, 'E o puseram em cárcere com ganchos, e o levaram ao rei da Babilônia; meteram-no em fortalezas, para que sua voz não fosse mais ouvida nos montes de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 10, 'Tua mãe era como uma videira em teu sangue, plantada junto às águas; que frutificava e era cheia de ramos, por causa das muitas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 11, 'E ela tinha varas fortes para cetros de senhores; e sua estatura se levantava por encima entre os ramos; e sua altura podia ser vista com a multidão de seus ramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 12, 'Porém foi arrancada com furor, derrubada na terra, e vento oriental secou seu fruto; suas fortes varas foram quebradas, e se secaram; o fogo as consumiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 13, 'E agora está plantada no deserto, em terra seca e sedenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 19, 14, 'E saiu fogo da uma vara de seus ramos, que consumido seu fruto; de modo que nela não há mais vara forte, cetro para senhorear.Esta é a lamentação, e para lamentação servirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 1, 'E aconteceu no sétimo ano, no quinto [mês] , aos dez do mês, que vieram alguns dos anciãos de Israel para consultarem ao SENHOR, e se assentaram diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 2, 'Então veio a mim palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 3, 'Filho do homem, fala aos anciãos de Israel, e dize-lhes: Assim diz o Senhor DEUS: Viestes vós para me consultar? Vivo eu, que eu não deixarei ser consultado por vós, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 4, 'Por acaso tu os julgarias, julgarias tu, ó filho do homem? Notifica-lhes as abominações de seus pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 5, 'E dize-lhes: Assim diz o Senhor DEUS: No dia em que escolhi a Israel, fiz juramento para a descendência da casa de Jacó, e me tornei conhecido por eles na terra do Egito, e fiz juramento para eles, dizendo: Eu sou o SENHOR vosso Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 6, 'Naquele dia eu lhes fiz juramento de que os tiraria da terra do Egito para uma terra que eu já tinha observado para eles, que corre leite e mel, a qual é a mais bela de todas as terras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 7, 'Então eu lhes disse: Cada um lance fora as abominações de seus olhos, e não vos contamineis com os ídolos do Egito. Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 8, 'Porém eles se rebelaram contra mim, e não quiseram me ouvir; não lançaram fora as abominações de seus olhos, nem deixaram os ídolos do Egito; por isso disse que derramaria meu furor sobre eles, para cumprir meu ira contra eles no meio da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 9, 'Porém fiz por favor a meu nome, para que não fosse profanado diante olhos das nações no meio das quais estavam, pelas quais eu fui conhecido diante dos olhos delas, ao tirá-los da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 10, 'Por isso eu os tirei da terra do Egito, e os levei ao deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 11, 'E lhes dei meus estatutos, e lhes declarei meus juízos, os quais se o homem os fizer, por eles viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 12, 'E também lhes dei meus sábados para que servissem de sinal entre mim e eles, para que soubessem que eu sou o SENHOR, que os santifico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 13, 'Mas a casa de Israel se rebelou contra mim no deserto: não andaram em meus estatutos, rejeitaram meus juízos, os quais se o homem os fizer, por eles viverá; e profanaram grandemente meus sábados. Então eu disse que derramaria meu furor sobre eles no deserto, para os consumir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 14, 'Porém fiz por favor a meu nome, para que não fosse profanado diante dos olhos das nações, diante de cujos olhos os tirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 15, 'Contudo eu lhes jurei no deserto de que não os traria para a terra que havia lhes dado, que corre leite e mel, a qual é a mais bela de todas as terras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 16, 'Porque rejeitaram meus juízos, não andaram em meus estatutos, e profanaram meus sábados; porque seus corações seguiam seus ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 17, 'Porém meu olho os poupou, não os destruindo, nem os consumindo no deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 18, 'Em vez disso, eu disse a seus filhos no deserto: Não andeis nos estatutos de vossos pais, nem guardeis seus juízos, nem vos contamineis com seus ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 19, 'Eu sou o SENHOR vosso Deus; andai em meus estatutos, guardai meus juízos, e os praticai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 20, 'E santificai meus sábados, e sirvam de sinal entre mim e vós, para que saibais que eu sou o SENHOR, vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 21, 'Mas os filhos se rebelaram contra mim; não andaram em meus estatutos, nem guardaram meus juízos fazê-los, os quais se o homem os cumprir, por eles viverá; [e] profanaram meus sábados. Então eu disse que derramaria meu furor sobre eles, para cumprir minha ira contra eles no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 22, 'Porém contive minha mão, e fiz por favor a meu nome, para que não fosse profanado diante dos olhos das nações, diante de cujos olhos os tirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 23, 'E também lhes jurei no deserto que os espalharia entre as nações, e que os dispersaria pelas terras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 24, 'Porque não praticaram meus juízos, rejeitaram meus estatutos, profanaram meus sábados, e seus olhos seguiram os ídolos de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 25, 'Por isso eu também lhes dei estatutos que não eram bons, e juízos pelos quais não viveriam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 26, 'E os contaminei em suas ofertas, em que faziam passar pelo fogo todo primogênito, para eu os assolar, a fim de que soubessem que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 27, 'Portanto, filho do homem, fala à casa de Israel, e dize-lhes: Assim diz o Senhor DEUS: Até nisto vossos pais me afrontaram quando transgrediram contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 28, 'Porque quando eu os trouxe para a terra da qual eu tinha jurado que lhes daria, então olharam para todo morro alto e para toda árvore espessa, e ali sacrificaram suas sacrifícios, e ali deram suas ofertas irritantes, e ali derramaram suas ofertas de bebidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 29, 'E eu lhes disse: Que alto é esse para onde vós vais? E seu nome foi chamado Bamá até o dia de hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 30, 'Por isso dize à casa de Israel: Assim diz o Senhor DEUS: Por acaso [não] vos contaminais assim como vossos pais, e vos prostituís segundo suas abominações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 31, 'Quando ofereceis vossas ofertas, e fazeis passar vossos filhos pelo fogo, vós estais contaminados com todos os vossos ídolos até hoje. E deixaria eu ser consultado por vós, ó casa de Israel? Vivo eu, diz o Senhor DEUS, que não deixarei ser consultado por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 32, 'E o que vós tendes pensado de maneira nenhuma sucederá. Pois vós dizeis: Seremos como as nações, como as famílias das terras, servindo à madeira e à pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 33, 'Vivo eu, diz o Senhor DEUS, que reinarei sobre vós com mão forte, braço estendido, e ira derramada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 34, 'E vos tirarei dentre os povos, e vos ajuntarei das terras em que estais espalhados, com mão forte, braço estendido, e ira derramada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 35, 'E eu vos levarei ao deserto de povos, e ali entrarei em juízo convosco face a face,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 36, 'Tal como entrei em juízo com vossos pais no deserto da terra do Egito, assim entrarei em juízo convosco, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 37, 'E vos farei passar debaixo da vara, e vos levarei em vínculo do pacto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 38, 'E separarei dentre vós os rebeldes, e os que se transgrediram contra mim; da terra de suas peregrinações eu os tirarei, mas à terra de Israel não voltarão; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 39, 'E quanto a vós, ó casa de Israel, assim diz o Senhor DEUS: Ide, servi cada um a seus ídolos, e depois, se não quereis me ouvir; mas não profaneis mais meu santo nome com vossas ofertas, e com vossos ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 40, 'Porque em meu santo monte, no monte alto de Israel, diz o Senhor DEUS, ali me servirá toda a casa de Israel, ela toda, naquela terra; ali eu os aceitarei, e ali demandarei vossas ofertas, e as primícias de vossas dádivas, com todas as vossas coisas santas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 41, 'Com cheiro suave vos aceitarei, quando eu vos tirar dentre os povos, e vos ajuntar das terras em que estais espalhados; e serei santificado em vós diante dos olhos das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 42, 'E sabereis que eu sou o SENHOR, quando eu vos trouxer de volta à terra de Israel, à terra da qual jurei que daria a vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 43, 'E ali vos lembrareis de vossos caminhos e de todos os vossos atos em que vos contaminastes; e tereis nojo de vós mesmos, por causa de todos os vossos pecados que tendes cometido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 44, 'E sabereis que eu sou o SENHOR, quando fizer convosco por favor a meu nome, não conforme vossos maus caminhos, nem conforme vossos atos corruptos, ó casa de Israel, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 45, 'E veio a mim palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 46, 'Filho do homem, dirige teu rosto em direção ao sul, derrama [tua palavra] ao sul, e profetiza contra o bosque do campo do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 47, 'E dize ao bosque do sul: Ouve a palavra do SENHOR! Assim diz o Senhor DEUS: Eis que eu acenderei em ti um fogo, que consumirá em ti toda árvore verde, e toda árvore seca; a chama do fogo não se apagará, e com ela serão queimados todos os rostos, desde o sul até o norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 48, 'E toda carne verá que eu, o SENHOR, o acendi; não se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 20, 49, 'Então eu disse: Ah, Senhor DEUS! Eles dizem de mim: Por acaso não é este um inventor de parábolas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 2, 'Filho do homem, dirige teu rosto contra Jerusalém, pronuncia contra os santuários, e profetiza contra a terra de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 3, 'E dize à terra de Israel: Assim diz o SENHOR: Eis que eu [sou] contra ti, e tirarei minha espada de sua bainha, e exterminarei de ti o justo e o perverso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 4, 'E dado que exterminarei de ti ao justo e o perverso, por isso minha espada sairá de sua bainha contra todos, desde o sul até o norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 5, 'E todos saberão que eu, o SENHOR, tirei minha espada de sua bainha; ela nunca mais voltará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 6, 'Porém tu, filho do homem, suspira com quebrantamento de lombos, e com amargura; suspira diante dos olhos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 7, 'E será que, quando te disserem: Por que tu suspiras? Então dirás: Por causa da notícia que vêm; e todo coração se dissolverá, todas as mãos se enfraquecerão, todo espírito se angustiará, e todos joelhos se desfarão em águas; eis que já vem, e ela se cumprirá, diz o Senhor DEUS'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 8, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 9, 'Filho do homem, profetiza, e dize: Assim diz o Senhor DEUS: Dize: A espada, a espada está afiada, e também polida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 10, 'Para degolar matança está afiada, para reluzir como relâmpago está polida. Por acaso nos alegraremos? A vara de meu filho despreza toda árvore.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 11, 'E ele a deu para polir, para usar dela com a mão; esta espada está afiada, e esta polida está, para a entregar na mão do matador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 12, 'Grita e uiva, ó filho do homem; porque esta será contra meu povo, será contra todos os príncipes de Israel. Entregues à de espada são os do meu povo; portanto bate na coxa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 13, 'Pois tem que haver provação. E o que seria se a vara que despreza não mais existir?diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 14, 'Por isso tu, filho do homem, profetiza, e bate uma mão com outra; por que a espada se dobrará até a terceira vez, a espada dos que forem mortos; esta é espada da grande matança que os cercará,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 15, 'Para que os corações desmaiem, e os tropeços se multipliquem; eu pus a ponta da espada contra todas as suas portas. Ah! Ela feita foi para reluzir, e preparada está para degolar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 16, '[Ó espada] , move-te; vira-te à direita, prepara-te, vira-te à esquerda, para onde quer que tua face te apontar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 17, 'E também eu baterei minhas mãos uma com a outra, e farei descansar minha ira. Eu, o SENHOR, falei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 18, 'E veio a mim a palavra de SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 19, 'E tu, filho do homem, propõe para ti dois caminhos por onde venha a espada do rei da Babilônia; ambos procederão de uma mesma terra; e põe um marco num lugar, põe um marco no começo do caminho da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 20, 'Propõe um caminho, por onde venha a espada contra Rabá dos filhos de Amom, e contra Judá, contra a fortificada Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 21, 'Porque o rei de Babilônia parará em uma encruzilhada, no começo de dois caminhos, para usar de adivinhação; ele sacudiu flechas, consultou ídolos, olhou o fígado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 22, 'A adivinhação será para a direita, sobre Jerusalém, para ordenar capitães, para abrir a boca à matança, para levantar a voz em grito, para pôr aríetes contra as portas, para levantar cercos, e edificar fortificações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 23, 'E isto será como uma adivinhação falsa aos olhos daqueles que com juramentos firmaram compromisso com eles; porém ele se lembrará da maldade, para que sejam presos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 24, 'Portanto, assim diz o Senhor DEUS: Dado que fizestes relembrar vossas maldades, manifestando vossas rebeliões, e revelando vossos pecados em todas vossos atos; por teres feito relembrar, sereis presos com a mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 25, 'E tu, profano e perverso príncipe de Israel, cujo dia do tempo do fim da maldade virá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 26, 'Assim diz o Senhor DEUS: Tira o turbante, tira a coroa; esta não será a mesma; ao humilde exaltarei, e ao exaltado humilharei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 27, 'Ruína! Ruína! Ruína a farei; e ela não será [restaurada] , até que venha aquele a quem lhe pertence por direito, e [a ele] a darei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 28, 'E tu, filho do homem, profetiza, e dize: Assim diz o Senhor DEUS sobre os filhos de Amom, e sua humilhação; Dize pois: A espada, a espada está desembainhada, polida para a matança, para destruir, para reluzir como relâmpago,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 29, 'Enquanto te profetizam falsidade, enquanto te adivinham mentira; para te porem sobre os pescoços dos perversos condenados à morte, cujo dia virá no tempo do fim da maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 30, 'Torna [tua espada] à sua bainha! No lugar onde foste criado, na terra de teu nascimento eu te julgarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 31, 'E derramarei sobre ti minha ira; assoprarei contra ti o fogo do meu furor, e te entregarei na mão de homens violentos, habilidosos em destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 21, 32, 'Para o fogo tu serás combustível; teu sangue estará no meio da terra; não haverá memória de ti; porque eu, o SENHOR, falei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 2, 'E tu, filho do homem, Por acaso julgarás tu, por acaso julgarás tu a cidade derramadora de sanguinária? Notifica-lhe, pois, todas as suas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 3, 'E dize: Assim disse o Senhor DEUS: Cidade que derrama sangue no meio de si, para que venha seu tempo, e que faz ídolos contra si mesma para se contaminar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 4, 'Fizeste-te culpada com teu sangue que derramaste, e te contaminaste com teus ídolos que fizeste; e fizeste aproximar teus dias, e chegado a teus anos; por isso te entreguei por humilhação às nações, e por escárnio a todas as terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 5, 'As que estão perto e as que estão longe de ti escarnecerão de ti, [que és] imunda de nome, e cheia de inquietação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 6, 'Eis que os príncipes de Israel, cada um conforme seu poder, estiveram em ti para derramarem sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 7, 'Desprezaram ao pai e à mãe em ti; trataram ao estrangeiro com opressão no meio de ti; oprimiram ao órfão e à viúva em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 8, 'Desprezaste minhas coisas santas, e profanaste meus sábados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 9, 'Caluniadores houve em ti, para derramarem sangue; e comeram sobre os montes em ti; praticaram lascívia no meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 10, 'Descobriram a nudez do pai ) em ti; abusaram da contaminada por menstruação em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 11, 'E um cometeu abominação com a mulher de seu próximo; e outro contaminou lascivamente sua nora; e outro abusou de sua irmã, filha de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 12, 'Suborno receberam em ti para derramarem sangue; juros e lucro tomaste, e exploraste gananciosamente o teu próximo, oprimindo-o; e esqueceste de mim, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 13, 'Mais eis que bati minhas mãos por causa de tua ganância que cometeste, e por causa de teu sangue, que houve no meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 14, 'Conseguirá, por acaso, ficar firme teu coração? Serão fortes tuas mãos nos dias em que eu agir contra ti? Eu, o SENHOR, falei, e farei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 15, 'E eu te dispersarei pelas nações, e te espalharei pelas terras; e acabarei de ti tua imundícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 16, 'Assim serás profanada em ti aos olhos das nações, e saberás que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 17, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 18, 'Filho do homem, a casa de Israel se tornou para mim em escórias; todos eles são cobre, estanho, ferro, e chumbo, no meio do forno; eles se tornaram escórias de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 19, 'Portanto assim diz o Senhor DEUS: Dado que todos vós vos tornastes em escórias, por isso eis que eu vos ajuntarei no meio de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 20, 'Como se ajunta prata, bronze, ferro, chumbo e estanho no meio do forno, para soprar fogo sobre eles para fundir, assim vos ajuntarei em minha ira e em meu furor, e [ali] vos deixarei, e vos fundirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 21, 'Eu vos reunirei, e soprarei sobre vós no fogo de meu furor, e no meio dela sereis fundidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 22, 'Como se funde a prata no meio do forno, assim sereis fundidos no meio dela; e sabereis que eu, o SENHOR, derramei meu furor sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 23, 'E veio a mim a palavra do SENHOR, dizendo:')
